//! Extended Renderer contracts generated by the pinned CesiumJS engine.
mod common;
use cesium_rs::{core::*, renderer::*};
use common::*;
use serde_json::{json, Value};
fn qualifier(v: &Value) -> PickColorQualifier {
    if s(v) == "uniform" {
        PickColorQualifier::Uniform
    } else {
        PickColorQualifier::In
    }
}
fn uniform_values(v: UniformValue) -> Vec<f64> {
    match v {
        UniformValue::Float(v) | UniformValue::Matrix { values: v, .. } => v.iter().map(|v| *v as f64).collect(),
        _ => panic!("Expected numeric derived uniform"),
    }
}
#[test]
fn renderer_extended_reference() {
    run(
        "renderer",
        "RendererAdvanced",
        |_| EXACT,
        |f, a| match f {
            "renderbufferConstants" => {
                ok(Value::Object(RenderbufferFormat::ALL.iter().map(|v| (v.name().into(), json!(*v as u32))).collect()))
            }
            "renderbufferFormat" => ok(json!([
                RenderbufferFormat::validate(u(&a[0])),
                RenderbufferFormat::get_color_format(u(&a[0])) as u32
            ])),
            "combined" => {
                let source = ShaderSource {
                    sources: vec![s(&a[0]).into()],
                    defines: vec!["TEST 2".into(), "TEST 1".into()],
                    ..Default::default()
                };
                ok(source
                    .combine(
                        a[1].as_bool().unwrap(),
                        ShaderCapabilities { texture_float_linear: true, floating_point_texture: true },
                        a[2].as_bool().unwrap(),
                    )
                    .unwrap())
            }
            "pick" => {
                let q = qualifier(&a[1]);
                let src = ShaderSource {
                    sources: vec![s(&a[0]).into()],
                    defines: vec!["B".into(), "A".into()],
                    include_built_ins: a[2].as_bool().unwrap(),
                    pick_color_qualifier: Some(q),
                };
                ok(json!([
                    src.cache_key(),
                    ShaderSource::create_pick_vertex_shader_source(s(&a[0])),
                    ShaderSource::create_pick_fragment_shader_source(s(&a[0]), q),
                    src.combine_webgl2(true, ShaderCapabilities::default()).unwrap()
                ]))
            }
            "varyings" => {
                let source = ShaderSource {
                    sources: vec![s(&a[0]).into()],
                    defines: list(&a[1], |v| s(v).into()),
                    ..Default::default()
                };
                ok(json!([source.find_normal_varying(), source.find_position_varying()]))
            }
            "demodernize" => ok(demodernize_shader(s(&a[0]), a[1].as_bool().unwrap())),
            "builder" => {
                let mut b = ShaderBuilder::default();
                let d = ShaderDestination(u(&a[0]));
                b.set_position_attribute("vec3", "position").unwrap();
                b.add_attribute(s(&a[1]), "transform");
                b.add_attribute("vec4", "color");
                b.add_define("SOLID", None, d);
                b.add_uniform("float", "scale", d);
                b.add_varying("vec3", "normal", Some("flat"));
                b.add_struct("s", "Attributes", d);
                b.add_struct_field("s", "vec3", "position").unwrap();
                b.add_function("f", "float scaleValue(float x)", d);
                b.add_function_lines("f", &["return x * 2.0;"]).unwrap();
                b.add_vertex_lines(&["void main(){gl_Position=vec4(position,1.);}"]);
                b.add_fragment_lines(&["void main(){out_FragColor=vec4(1.);}"]);
                let value = |b: &ShaderBuilder| {
                    let (v, f) = b.sources();
                    json!([v.sources, v.defines, f.sources, f.defines, b.attribute_locations()])
                };
                ok(json!([value(&b), value(&b.clone())]))
            }
            "automaticDeclaration" => ok(automatic_uniforms()[s(&a[0])].declaration(s(&a[0])).unwrap()),
            "uniformMatrices" => {
                let mut state = UniformState::default();
                state.model = Matrix4::from_uniform_scale(n(&a[0]));
                let view = Matrix4::from_translation(Cartesian3::new(1., 2., 3.));
                state.update_camera(view, view.inverse_transformation(), Cartesian3::new(1000000., 2000000., 3000000.));
                let projection = Matrix4::compute_perspective_field_of_view(1., 1.5, 0.1, 100.);
                state.update_frustum(projection, Some(projection), 0., 0.);
                state.viewport = Viewport { x: 2, y: 3, width: 100, height: 200 };
                ok(json!(a[1]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|name| uniform_values(state.get(s(name)).unwrap().unwrap()))
                    .collect::<Vec<_>>()))
            }
            "precision" => {
                let (text, names) = cesium_rs::renderer::shader_precision::handle_uniform_precision_mismatches(
                    s(&a[0]),
                    s(&a[1]),
                    a[2].as_bool().unwrap(),
                    a[2].as_bool().unwrap(),
                );
                ok(json!([text, names]))
            }
            "stateCacheRelease" => {
                let mut cache = RenderStateCache::default();
                let state = RenderState::default();
                let a = cache.from_cache(state.clone()).unwrap();
                let b = cache.from_cache(state.clone()).unwrap();
                cache.remove_from_cache(&state);
                let c = cache.from_cache(state.clone()).unwrap();
                cache.remove_from_cache(&state);
                cache.remove_from_cache(&state);
                let d = cache.from_cache(state).unwrap();
                ok(json!([std::rc::Rc::ptr_eq(&a, &b), std::rc::Rc::ptr_eq(&a, &c), std::rc::Rc::ptr_eq(&a, &d)]))
            }
            "stateCache" => {
                let mut c = RenderStateCache::default();
                let a = c.from_cache(RenderState::default()).unwrap();
                let b = c.from_cache(RenderState::default()).unwrap();
                let mut s = RenderState::default();
                s.depth_test.enabled = true;
                let d = c.from_cache(s).unwrap();
                c.clear_cache();
                let e = c.from_cache(RenderState::default()).unwrap();
                ok(json!([
                    std::rc::Rc::ptr_eq(&a, &b),
                    std::rc::Rc::ptr_eq(&a, &d),
                    a.depth_test.enabled,
                    d.depth_test.enabled,
                    std::rc::Rc::ptr_eq(&a, &e)
                ]))
            }
            _ => None,
        },
    );
}
#[test]
fn builtin_cycles_are_reported() {
    let source = ShaderSource::new("void main(){czm_a();}");
    let registry = std::collections::HashMap::from([
        ("czm_a".into(), "void czm_a(){czm_b();}".into()),
        ("czm_b".into(), "void czm_b(){czm_a();}".into()),
    ]);
    assert!(source.combine_with_registry(false, ShaderCapabilities::default(), true, &registry).is_err());
}
